import zeros = require( '@stdlib/ndarray/zeros' );
import ndarraylike2descriptor = require( '@stdlib/ndarray/base/ndarraylike2descriptor' );
import setDescriptorOffsets = require( './index' );


// TESTS //

// The function returns an array...
{
	const v = ndarraylike2descriptor( zeros( [ 1 ] ) );

	setDescriptorOffsets( [ v ], [ 0 ] ); // $ExpectType Descriptor[]
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object containing ndarray-like objects...
{
	setDescriptorOffsets( '5', [ 0 ] ); // $ExpectError
	setDescriptorOffsets( 5, [ 0 ] ); // $ExpectError
	setDescriptorOffsets( true, [ 0 ] ); // $ExpectError
	setDescriptorOffsets( false, [ 0 ] ); // $ExpectError
	setDescriptorOffsets( null, [ 0 ] ); // $ExpectError
	setDescriptorOffsets( {}, [ 0 ] ); // $ExpectError
	setDescriptorOffsets( [ '5' ], [ 0 ] ); // $ExpectError
	setDescriptorOffsets( ( x: number ): number => x, [ 0 ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an array-like object containing ndarray-like objects...
{
	const v = ndarraylike2descriptor( zeros( [ 1 ] ) );

	setDescriptorOffsets( [ v ], '5' ); // $ExpectError
	setDescriptorOffsets( [ v ], 5 ); // $ExpectError
	setDescriptorOffsets( [ v ], true ); // $ExpectError
	setDescriptorOffsets( [ v ], false ); // $ExpectError
	setDescriptorOffsets( [ v ], null ); // $ExpectError
	setDescriptorOffsets( [ v ], {} ); // $ExpectError
	setDescriptorOffsets( [ v ], [ '5' ] ); // $ExpectError
	setDescriptorOffsets( [ v ], ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const arr = [ zeros( [ 1 ] ) ];

	setDescriptorOffsets(); // $ExpectError
	setDescriptorOffsets( arr ); // $ExpectError
	setDescriptorOffsets( arr, [ 0 ], {} ); // $ExpectError
}
